window.REPORT_PRELOAD_CACHE["LRCX.html"] = {"version":"86d779ce9544ca19d49ee6746e5d9eae395601d0fa80896c914259e18f2c8498","html":"<!DOCTYPE html>\n<html lang=\"zh-CN\" class=\"scroll-smooth\">\n<head>\n <meta charset=\"UTF-8\" />\n <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\" />\n <title>泛林集团 Lam Research (NASDAQ: LRCX) 深度研究报告：全球半导体刻蚀与淀积设备霸主、先进存储与 GAA 晶体管核心赋能者</title>\n <!-- Tailwind CSS -->\n <script src=\"https://cdn.tailwindcss.com\"></script>\n <!-- Chart.js -->\n <script src=\"https://cdn.jsdelivr.net/npm/chart.js\"></script>\n <!-- Google Fonts: Inter + Noto Sans SC + JetBrains Mono -->\n <link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n <link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n <link href=\"https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&family=JetBrains+Mono:wght@400;600;700&family=Noto+Sans+SC:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n\n <script>\n tailwind.config = {\n darkMode: 'class',\n theme: {\n extend: {\n fontFamily: {\n sans: ['Inter', 'Noto Sans SC', 'system-ui', '-apple-system', 'sans-serif'],\n mono: ['JetBrains Mono', 'monospace'],\n },\n colors: {\n navy: {\n 950: '#070B14',\n 900: '#0F172A',\n 800: '#1E293B',\n 700: '#334155',\n },\n lamorange: {\n 500: '#FF6B00',\n 600: '#E05E00',\n 400: '#FF8833',\n },\n accent: {\n 500: '#3B82F6',\n 600: '#2563EB',\n },\n teal: {\n 500: '#06B6D4',\n 600: '#0891B2',\n }\n }\n }\n }\n }\n </script>\n\n <style>\n ::-webkit-scrollbar {\n width: 6px;\n height: 6px;\n }\n ::-webkit-scrollbar-track {\n background: transparent;\n }\n ::-webkit-scrollbar-thumb {\n background: #94A3B8;\n border-radius: 3px;\n }\n .dark ::-webkit-scrollbar-thumb {\n background: #475569;\n }\n\n @media print {\n #sidebar, #mobile-header, #theme-toggle-btn, .no-print {\n display: none !important;\n }\n main {\n margin-left: 0 !important;\n padding: 0 !important;\n }\n section {\n break-inside: avoid;\n }\n }\n\n .report-card {\n transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;\n }\n .report-card:hover {\n transform: translateY(-2px);\n }\n\n .nav-link.active {\n background: linear-gradient(90deg, rgba(255, 107, 0, 0.18) 0%, rgba(6, 182, 212, 0.06) 100%);\n border-left: 3px solid #FF6B00;\n color: #FFFFFF;\n font-weight: 600;\n }\n </style>\n</head>\n<body class=\"bg-[#F8FAFC] text-[#1E293B] dark:bg-navy-950 dark:text-slate-100 antialiased selection:bg-lamorange-500 selection:text-white transition-colors duration-200\">\n\n <!-- 顶部阅读进度条 -->\n <div class=\"fixed top-0 left-0 right-0 h-1 z-50 bg-slate-200/70 dark:bg-navy-800\">\n <div id=\"reading-progress\" class=\"h-full bg-gradient-to-r from-lamorange-500 via-amber-500 to-teal-500 w-0 transition-all duration-150\"></div>\n </div>\n\n <!-- 移动端顶部导航栏 -->\n <header id=\"mobile-header\" class=\"lg:hidden sticky top-0 z-40 bg-navy-900 text-white border-b border-slate-800 px-4 py-3 flex items-center justify-between shadow-md\">\n <div class=\"flex items-center space-x-2.5\">\n <div class=\"w-8 h-8 rounded-lg bg-gradient-to-br from-lamorange-500 to-lamorange-600 flex items-center justify-center font-extrabold text-white shadow\">\n LRCX\n </div>\n <div>\n <div class=\"text-[11px] text-lamorange-400 font-semibold tracking-wider uppercase\">NASDAQ: LRCX · Equity Research</div>\n <div class=\"text-sm font-bold leading-tight\">泛林集团 Lam Research 深度研究报告</div>\n </div>\n </div>\n <div class=\"flex items-center space-x-2\">\n <button onclick=\"toggleTheme()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-slate-300\" aria-label=\"切换阅读主题\">\n <svg class=\"w-5 h-5 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <svg class=\"w-5 h-5 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n </button>\n <button id=\"mobile-menu-btn\" onclick=\"toggleMobileMenu()\" class=\"p-2 rounded-lg bg-navy-800 hover:bg-navy-700 text-white\" aria-label=\"打开目录\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M4 6h16M4 12h16M4 18h16\"/></svg>\n </button>\n </div>\n </header>\n\n <!-- 移动端折叠抽屉菜单 -->\n <div id=\"mobile-drawer\" class=\"fixed inset-0 z-50 hidden lg:hidden\">\n <div class=\"fixed inset-0 bg-slate-900/70 backdrop-blur-sm\" onclick=\"toggleMobileMenu()\"></div>\n <nav class=\"relative w-72 max-w-[80vw] h-full bg-navy-900 text-slate-300 flex flex-col justify-between p-5 overflow-y-auto shadow-2xl\">\n <div>\n <div class=\"flex items-center justify-between pb-4 border-b border-slate-800\">\n <span class=\"font-bold text-white text-base\">LRCX 研报目录导航</span>\n <button onclick=\"toggleMobileMenu()\" class=\"p-1.5 rounded-lg text-slate-400 hover:text-white\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M6 18L18 6M6 6l12 12\"/></svg>\n </button>\n </div>\n <ul class=\"mt-4 space-y-1.5 text-sm\">\n <li><a href=\"#sec-exec\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">00. 执行摘要与核心指标</a></li>\n <li><a href=\"#sec-biz\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">01. 业务与刻蚀/淀积技术架构</a></li>\n <li><a href=\"#sec-moat\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">02. 行业地位与四重核心护城河</a></li>\n <li><a href=\"#sec-comp\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">03. 同行竞争格局横向对比</a></li>\n <li><a href=\"#sec-fin\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">04. 财务健康与估值体系</a></li>\n <li><a href=\"#sec-inv\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">05. 投资决策与风险配置</a></li>\n <li><a href=\"#sec-kpi\" onclick=\"toggleMobileMenu()\" class=\"block px-3 py-2.5 rounded-lg hover:bg-navy-800 hover:text-white\">06. 季度跟踪 KPI 核查清单</a></li>\n </ul>\n </div>\n <div class=\"pt-4 border-t border-slate-800 text-xs text-slate-400\">\n <p>全球半导体设备与刻蚀技术研究组</p>\n <p class=\"mt-1\">数据基准：2026年11月 (FY26 / FY27E)</p>\n </div>\n </nav>\n </div>\n\n <!-- 桌面端左侧固定侧边导航栏 -->\n <aside id=\"sidebar\" class=\"hidden lg:flex fixed top-0 left-0 bottom-0 w-[280px] bg-[#0F172A] text-slate-300 flex-col justify-between border-r border-slate-800 z-30 select-none\">\n <div>\n <div class=\"p-5 border-b border-slate-800/80\">\n <div class=\"flex items-center space-x-3\">\n <div class=\"w-10 h-10 rounded-xl bg-gradient-to-br from-lamorange-500 to-lamorange-600 flex items-center justify-center text-white font-extrabold text-base shadow-lg shadow-lamorange-500/25\">\n LRCX\n </div>\n <div>\n <span class=\"inline-block text-[10px] font-bold tracking-widest uppercase text-lamorange-400 bg-lamorange-500/15 px-2 py-0.5 rounded\">NASDAQ: LRCX</span>\n <h2 class=\"text-white font-bold text-base mt-0.5 tracking-tight\">泛林集团深度研报</h2>\n </div>\n </div>\n <p class=\"text-xs text-slate-400 mt-2.5 leading-relaxed\">\n 全球半导体刻蚀与淀积设备霸主 · 3D NAND 与先进逻辑 GAA/DRAM 核心赋能者\n </p>\n </div>\n\n <div class=\"px-5 py-3 bg-navy-950/70 border-b border-slate-800/80 space-y-1.5 text-xs\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">FY2025 全年营收</span>\n <span class=\"font-mono font-bold text-white\">$17.8B <span class=\"text-lamorange-400\">(+24%)</span></span>\n </div>\n <div class=\"flex items-center justify-between\">\n <span class=\"text-slate-400\">FY2026E 营收共识</span>\n <span class=\"font-mono font-bold text-teal-400\">~$21.5B <span class=\"text-slate-400\">(+21%)</span></span>\n </div>\n <div class=\"flex items-center justify-between pt-1 border-t border-slate-800/70\">\n <span class=\"text-slate-400\">远期估值锚</span>\n <span class=\"font-mono font-bold text-lamorange-400\">~20.5x P/E · PEG 0.45</span>\n </div>\n </div>\n\n <div class=\"px-3 py-3.5 overflow-y-auto max-h-[calc(100vh-310px)]\">\n <div class=\"px-3 mb-2 text-[11px] font-semibold uppercase tracking-wider text-slate-500\">核心研究章节</div>\n <nav id=\"desktop-nav\" class=\"space-y-1 text-[13px]\">\n <a href=\"#sec-exec\" data-target=\"sec-exec\" class=\"nav-link active flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-lamorange-400 mr-2\">00</span>执行摘要与核心指标</span>\n </a>\n <a href=\"#sec-biz\" data-target=\"sec-biz\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">01</span>业务与刻蚀/淀积架构</span>\n </a>\n <a href=\"#sec-moat\" data-target=\"sec-moat\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">02</span>行业地位与四重护城河</span>\n </a>\n <a href=\"#sec-comp\" data-target=\"sec-comp\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">03</span>同行竞争格局横向对比</span>\n </a>\n <a href=\"#sec-fin\" data-target=\"sec-fin\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">04</span>财务健康与估值体系</span>\n </a>\n <a href=\"#sec-inv\" data-target=\"sec-inv\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">05</span>投资决策与风险配置</span>\n </a>\n <a href=\"#sec-kpi\" data-target=\"sec-kpi\" class=\"nav-link flex items-center justify-between px-3 py-2 rounded-r-lg text-slate-300 hover:bg-navy-800/70 hover:text-white transition-all\">\n <span><span class=\"text-xs font-mono text-slate-500 mr-2\">06</span>季度跟踪 KPI 核查清单</span>\n </a>\n </nav>\n </div>\n </div>\n\n <div class=\"p-4 border-t border-slate-800/80 bg-navy-950/50 space-y-2.5\">\n <div class=\"flex items-center justify-between\">\n <span class=\"text-xs text-slate-400\">阅读模式切换</span>\n <button id=\"theme-toggle-btn\" onclick=\"toggleTheme()\" class=\"flex items-center space-x-1.5 px-2.5 py-1.5 rounded-lg bg-navy-800 hover:bg-navy-700 text-xs font-medium text-slate-200 border border-slate-700 transition\">\n <svg class=\"w-3.5 h-3.5 text-amber-400 hidden dark:block\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 3v1m0 16v1m9-9h-1M4 12H3m15.364 6.364l-.707-.707M6.343 6.343l-.707-.707m12.728 0l-.707.707M6.343 17.657l-.707.707M16 12a4 4 0 11-8 0 4 4 0 018 0z\"/></svg>\n <svg class=\"w-3.5 h-3.5 text-lamorange-400 dark:hidden\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M20.354 15.354A9 9 0 018.646 3.646 9.003 9.003 0 0012 21a9.003 9.003 0 008.354-5.646z\"/></svg>\n <span class=\"dark:hidden\">深色护眼模式</span>\n <span class=\"hidden dark:inline\">机构亮色模式</span>\n </button>\n </div>\n <button onclick=\"window.print()\" class=\"w-full flex items-center justify-center space-x-2 py-2 px-3 rounded-lg bg-lamorange-500 hover:bg-lamorange-600 text-white text-xs font-extrabold transition shadow-sm\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M17 17h2a2 2 0 002-2v-4a2 2 0 00-2-2H5a2 2 0 00-2 2v4a2 2 0 002 2h2m2 4h6a2 2 0 002-2v-4a2 2 0 00-2-2H9a2 2 0 00-2 2v4a2 2 0 002 2zm8-12V5a2 2 0 00-2-2H9a2 2 0 00-2 2v4h10z\"/></svg>\n <span>打印 / 导出 PDF 研报</span>\n </button>\n </div>\n </aside>\n\n <!-- 主内容区 -->\n <main class=\"lg:ml-[280px] min-h-screen\">\n <div class=\"max-w-6xl mx-auto px-4 sm:px-8 py-8 lg:py-12 space-y-12\">\n\n <!-- 00. Hero 研报封面区与执行摘要 -->\n <section id=\"sec-exec\" class=\"scroll-mt-20\">\n <div class=\"flex flex-wrap items-center justify-between gap-3 mb-4 text-xs text-slate-500 dark:text-slate-400\">\n <div class=\"flex flex-wrap items-center gap-2\">\n <span class=\"px-2.5 py-1 rounded-md bg-lamorange-500/15 text-lamorange-600 dark:text-lamorange-400 font-bold border border-lamorange-500/30\">评级：强烈买入 / 半导体设备核心配置</span>\n <span class=\"px-2.5 py-1 rounded-md bg-slate-200/70 dark:bg-navy-800 text-slate-700 dark:text-slate-300 font-medium\">周期：FY2025–FY2027 3D NAND 与 GAA 刻蚀红利</span>\n </div>\n <div class=\"flex items-center space-x-3 font-mono\">\n <span>覆盖时间：2026年11月</span>\n <span>NASDAQ: LRCX</span>\n </div>\n </div>\n\n <div class=\"relative overflow-hidden rounded-2xl bg-gradient-to-br from-navy-900 via-navy-800 to-slate-900 text-white p-6 sm:p-10 shadow-xl border border-slate-700/70\">\n <div class=\"absolute inset-0 opacity-10 pointer-events-none\" style=\"background-image: radial-gradient(#FF6B00 1.2px, transparent 1.2px); background-size: 24px 24px;\"></div>\n <div class=\"relative z-10\">\n <div class=\"inline-flex items-center space-x-2 px-3 py-1 rounded-full bg-lamorange-500/20 border border-lamorange-500/40 text-lamorange-400 text-xs font-semibold mb-4\">\n <span class=\"w-2 h-2 rounded-full bg-lamorange-400 animate-pulse\"></span>\n <span>CORE THESIS · 全球半导体刻蚀与淀积绝对霸主 × 3D NAND 堆叠升级与逻辑 GAA 架构演进</span>\n </div>\n <h1 class=\"text-2xl sm:text-4xl font-extrabold tracking-tight leading-tight text-white\">\n 泛林集团 Lam Research (NASDAQ: LRCX) 深度研究报告：全球半导体刻蚀与淀积设备霸主、先进存储与 GAA 晶体管核心赋能者\n </h1>\n <p class=\"mt-4 text-sm sm:text-base text-slate-300 max-w-4xl leading-relaxed\">\n 泛林集团（Lam Research）作为全球半导体晶圆制造设备（WFE）三巨头之一，在<strong class=\"text-white\">等离子体刻蚀（Plasma Etch）</strong>与<strong class=\"text-lamorange-400\">薄膜淀积（Deposition）</strong>领域占据全球绝对垄断地位。\n FY2025 全年营收达 <strong class=\"text-lamorange-400\">$17.8B (+24%)</strong>，毛利率稳居 <strong class=\"text-white\">48%–50%</strong> 高位。随着 3D NAND 向 300层+ 垂直堆叠演进、逻辑芯片迈向 GAA 纳米制程及高带宽内存（HBM）TSV 刻蚀需求爆发，远期 P/E 维持在 <strong class=\"text-emerald-400\">~20.5x（PEG 0.45）</strong>，具备极高成长确定性与安全边际。\n </p>\n\n <div class=\"mt-6 pt-6 border-t border-slate-700/80 grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">刻蚀技术绝对统治力</div>\n <div class=\"text-white font-semibold\">在高深宽比（HAR）刻蚀与 3D NAND 垂直孔道加工中市占率超 55%</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">存储与逻辑双轮驱动</div>\n <div class=\"text-lamorange-400 font-semibold\">受益于 NAND 堆叠层数翻倍与逻辑 GAA 架构转换带来的高价值量设备增量</div>\n </div>\n <div class=\"bg-white/5 rounded-xl p-3.5 border border-white/10\">\n <div class=\"text-slate-400 font-medium mb-1\">卓越财务与股东回报</div>\n <div class=\"text-teal-400 font-semibold\">FY26E 营收共识 ~$21.5B，远期 P/E 仅 ~20.5x，自由现金流充沛且回购力度强劲</div>\n </div>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mt-6\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>FY2025 全年总营收</span>\n <span class=\"p-1.5 rounded-lg bg-lamorange-500/15 text-lamorange-600 dark:text-lamorange-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M13 7h8m0 0v8m0-8l-8 8-4-4-6 6\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">$17.8B</span>\n <span class=\"text-xs font-bold text-lamorange-600 dark:text-lamorange-400 bg-lamorange-500/15 px-2 py-0.5 rounded\">+24% YoY</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 存储器复苏与 AI 逻辑芯片先进制程产能扩张双轮驱动，全年业绩保持强劲双位数增长。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>毛利率与营业利润率</span>\n <span class=\"p-1.5 rounded-lg bg-accent-500/10 text-accent-600 dark:text-accent-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M5 12h14M5 12a2 2 0 01-2-2V6a2 2 0 012-2h14a2 2 0 012 2v4a2 2 0 01-2 2M5 12a2 2 0 00-2 2v4a2 2 0 002 2h14a2 2 0 002-2v-4a2 2 0 00-2-2m-2-4h.01M17 16h.01\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">48.5%</span>\n <span class=\"text-xs font-bold text-accent-600 dark:text-accent-400 bg-accent-500/10 px-2 py-0.5 rounded\">OPM ~32.2%</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 高端刻蚀设备组合及 Installed Base（装机量）高利润服务收入带动，盈利能力稳居行业前列。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>系统制造与装机量服务 (CSBG)</span>\n <span class=\"p-1.5 rounded-lg bg-teal-500/10 text-teal-600 dark:text-teal-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$6.2B</span>\n <span class=\"text-xs font-bold text-teal-600 dark:text-teal-400 bg-teal-500/10 px-2 py-0.5 rounded\">高黏性现金流</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 庞大的全球已装机设备基数带来持续稳定的备件、升级与技术服务收入，平抑周期波动。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between text-xs font-semibold text-slate-500 dark:text-slate-400\">\n <span>FY2026E 预期与估值</span>\n <span class=\"p-1.5 rounded-lg bg-emerald-500/10 text-emerald-600 dark:text-emerald-400\">\n <svg class=\"w-4 h-4\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m5.618-4.016A11.955 11.955 0 0112 2.944a11.955 11.955 0 01-8.618 3.04A12.02 12.02 0 003 9c0 5.591 3.824 10.29 9 11.622 5.176-1.332 9-6.03 9-11.622 0-1.042-.133-2.052-.382-3.016z\"/></svg>\n </span>\n </div>\n <div class=\"mt-3 flex items-baseline space-x-2\">\n <span class=\"text-3xl font-extrabold text-slate-900 dark:text-white font-mono\">~$21.5B</span>\n <span class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2 py-0.5 rounded\">Fwd P/E ~20.5x</span>\n </div>\n <p class=\"mt-2 text-xs text-slate-500 dark:text-slate-400 leading-relaxed\">\n 存储换代与 AI 驱动推动 FY26 营收跨越 $20B 大关，PEG 约 0.45，估值极具吸引力。\n </p>\n </div>\n </div>\n </section>\n\n <!-- 一、业务与技术制程架构 -->\n <section id=\"sec-biz\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-lamorange-600 dark:text-lamorange-400\">Section 01 · Business & Technology Architecture</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">一、 业务与刻蚀/淀积技术架构：精细化微观加工的全球执牛耳者</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">FY2025 总营收 $17.8B · 刻蚀与淀积双核驱动</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6\">\n <div class=\"lg:col-span-7 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-wrap items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\" id=\"biz-chart-title\">FY2021–FY2026E 营收演进与下游存储/逻辑结构占比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-0.5\" id=\"biz-chart-sub\">存储器（NAND/DRAM）与先进逻辑芯片复苏带动年营收向 $21B+ 迈进</p>\n </div>\n <div class=\"inline-flex rounded-lg bg-slate-100 dark:bg-navy-800 p-1 text-xs no-print\">\n <button onclick=\"switchBizChart('evolution')\" id=\"btn-chart-evo\" class=\"px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-lamorange-600 dark:text-lamorange-400 shadow-sm transition\">视图A：营收演进</button>\n <button onclick=\"switchBizChart('segments')\" id=\"btn-chart-split\" class=\"px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition\">视图B：下游应用拆解</button>\n </div>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"bizArchitectureChart\"></canvas>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">半导体设备核心技术三大支柱</h3>\n <ul class=\"space-y-4 text-sm\">\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-lamorange-500/15 text-lamorange-600 dark:text-lamorange-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">1</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">等离子体刻蚀（Plasma Etch 霸主）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 涵盖 Conductor Etch（导体刻蚀）与 Dielectric Etch（介质刻蚀），在 3D NAND 超高深宽比（HAR）垂直孔道加工中市占率超越 <strong>55%</strong>，是纳米级微观雕刻的核心利器。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-teal-500/15 text-teal-600 dark:text-teal-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">2</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">薄膜淀积与原子层沉积（CVD / ALD）</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 依托 SABRE、ALTUS 等旗舰平台，在原子级厚度薄膜生长、填充与表面处理领域具备无可替代的技术优势，护航先进逻辑 GAA 晶体管与 DRAM 节点升级。\n </p>\n </div>\n </li>\n <li class=\"flex items-start space-x-3\">\n <span class=\"w-6 h-6 rounded-full bg-accent-500/15 text-accent-600 dark:text-accent-400 font-bold text-xs flex items-center justify-center shrink-0 mt-0.5\">3</span>\n <div>\n <div class=\"font-semibold text-slate-900 dark:text-white\">CSBG 装机量客户服务与可靠性清洗</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 全球数万台已装机设备提供高毛利的备件更换、升级改造及 Reliant 清洗设备服务，有效平抑半导体行业的周期性波动。\n </p>\n </div>\n </li>\n </ul>\n </div>\n <div class=\"mt-5 pt-4 border-t border-slate-100 dark:border-slate-800 flex items-center justify-between text-xs\">\n <span class=\"text-slate-500 dark:text-slate-400\">核心技术催化剂</span>\n <span class=\"font-bold text-lamorange-600 dark:text-lamorange-400\">3D NAND 300层+ 刻蚀与逻辑 GAA 演进</span>\n </div>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-lamorange-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-lamorange-500/15 text-lamorange-600 dark:text-lamorange-400 text-xs font-bold\">核心支柱 · 占比 ~40%</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">NAND Flash</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">3D NAND 存储器制造</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 随着 3D NAND 从 100层向 300层+ 垂直堆叠演进，刻蚀深度与精度要求呈指数级上升，泛林集团的 cryogenic（深冷）刻蚀技术成为行业唯一标杆。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-lamorange-600 dark:text-lamorange-400 font-semibold\">\n 高深宽比刻蚀绝对统治者\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-accent-500/10 text-accent-600 dark:text-accent-400 text-xs font-bold\">增长引擎 · 占比 ~30%</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">Foundry & Logic</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">先进制程逻辑与代工（Foundry）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 伴随全球顶尖晶圆厂向 3nm 及 2nm GAA（全栅极）晶体管过渡，多重图形化（Multi-Patterning）与复杂薄膜淀积需求大幅推升单片晶圆设备价值量。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-slate-500\">\n GAA 架构与 3nm/2nm 节点赋能\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-teal-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">高景气度 · 占比 ~18%</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">DRAM & HBM</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">DRAM 与 HBM 内存制造</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n AI 算力对高带宽内存（HBM）的爆发式需求带动硅通孔（TSV）刻蚀与电镀需求大增，同时传统 DRAM 节点微缩持续推高设备 Intensity。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold\">\n HBM TSV 刻蚀与电镀核心供应商\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-indigo-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"px-2.5 py-1 rounded-md bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">现金奶牛 · 占比 ~32%</span>\n <span class=\"text-sm font-extrabold font-mono text-slate-900 dark:text-white\">CSBG Services</span>\n </div>\n <h3 class=\"text-base font-bold text-slate-900 dark:text-white\">装机量客户服务（CSBG）</h3>\n <p class=\"mt-2.5 text-xs sm:text-sm text-slate-600 dark:text-slate-300 leading-relaxed\">\n 依托全球庞大的已安装设备基数，提供高利润率的零备件、设备升级、技术支持及 Reliant 二手设备翻新服务，构筑穿越半导体周期的安全垫。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold\">\n 高毛利稳定现金流引擎\n </div>\n </div>\n </div>\n </section>\n\n <!-- 二、行业地位与四重核心护城河 -->\n <section id=\"sec-moat\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 02 · Industry Position & Economic Moat</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">二、 行业地位与四重核心护城河：微观雕刻专利壁垒与客户深度嵌入</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">护城河评级：极宽 (Wide Moat · 全球半导体刻蚀与淀积绝对双巨头之一)</span>\n </div>\n\n <div class=\"grid grid-cols-1 lg:grid-cols-12 gap-6 items-center\">\n <div class=\"lg:col-span-7 grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-lamorange-500/15 text-lamorange-600 dark:text-lamorange-400 flex items-center justify-center font-bold text-sm\">01</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">超高深宽比（HAR）刻蚀技术专利护城河</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 随着 3D NAND 突破 300层，刻蚀孔径极细且深，极易发生弯曲或畸变。泛林集团凭借独家的深冷刻蚀（Cryogenic Etch）技术与射频控制专利，构筑了竞争对手难以逾越的技术壁垒。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-accent-500/15 text-accent-600 dark:text-accent-400 flex items-center justify-center font-bold text-sm\">02</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">与全球顶尖晶圆厂的联合研发协同机制</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 设备厂商必须在芯片量产前 3–5 年与台积电、三星、美光及 SK 海力士等巨头联合开发工艺。泛林集团的设备在各大 Fab 核心产线中深度嵌入，转换客户的试错成本极高。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-teal-500/15 text-teal-600 dark:text-teal-400 flex items-center justify-center font-bold text-sm\">03</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">Installed Base 装机量网络效应</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 全球数万台运行中的泛林设备产生海量运行数据，反哺软件与硬件升级迭代。CSBG 服务的极高客户黏性确保了公司在半导体下行周期中依然能够维持健康的现金流与盈利。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center space-x-2.5 mb-2.5\">\n <span class=\"w-8 h-8 rounded-lg bg-indigo-500/15 text-indigo-600 dark:text-indigo-400 flex items-center justify-center font-bold text-sm\">04</span>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-sm\">刻蚀与淀积（Etch & Deposition）协同工艺平台</h3>\n </div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n 泛林能够同时提供刻蚀和薄膜淀积设备，在先进封装、多重图形化（SADP/SAQP）及垂直集成制造中，提供模块化的交钥匙解决方案，单台晶圆厂成套采购优势显著。\n </p>\n </div>\n </div>\n\n <div class=\"lg:col-span-5 bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-1\">半导体设备五维护城河量化雷达图</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">Lam Research vs Applied Materials (AMAT) vs Tokyo Electron (TEL)（满分 10 分）</p>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"moatRadarChart\"></canvas>\n </div>\n </div>\n </div>\n </section>\n\n <!-- 三、同行竞争格局横向对比 -->\n <section id=\"sec-comp\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-3\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-lamorange-600 dark:text-lamorange-400\">Section 03 · Global Competitive Landscape</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">三、 同行竞争格局横向对比：刻蚀领域双雄争霸，细分赛道优势明显</h2>\n </div>\n <div class=\"flex flex-wrap gap-1.5 text-xs no-print\" id=\"comp-filter-group\">\n <button onclick=\"filterCompetitors('all')\" data-filter=\"all\" class=\"comp-filter-btn active px-3 py-1.5 rounded-lg font-semibold bg-lamorange-500 text-white shadow-sm transition\">全部阵营</button>\n <button onclick=\"filterCompetitors('wfe')\" data-filter=\"wfe\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">全球顶级 WFE 设备巨头</button>\n <button onclick=\"filterCompetitors('etch')\" data-filter=\"etch\" class=\"comp-filter-btn px-3 py-1.5 rounded-lg font-medium bg-white dark:bg-navy-800 text-slate-600 dark:text-slate-300 border border-slate-200 dark:border-slate-700 hover:bg-slate-50 transition\">刻蚀与清洗细分对手</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl border border-slate-200 dark:border-slate-800 shadow-sm overflow-hidden\">\n <div class=\"overflow-x-auto\">\n <table class=\"w-full text-left border-collapse\">\n <thead>\n <tr class=\"bg-slate-100/80 dark:bg-navy-800/80 border-b border-slate-200 dark:border-slate-700 text-xs font-bold uppercase tracking-wider text-slate-600 dark:text-slate-300\">\n <th class=\"py-4 px-5 min-w-[180px]\">竞争厂商与核心领域</th>\n <th class=\"py-4 px-4 min-w-[130px]\">主营核心产品线</th>\n <th class=\"py-4 px-4 min-w-[140px]\">刻蚀与淀积全球地位</th>\n <th class=\"py-4 px-4 min-w-[135px]\">服务收入占比 (CSBG)</th>\n <th class=\"py-4 px-4 min-w-[115px]\">毛利率水平</th>\n <th class=\"py-4 px-5 min-w-[240px]\">核心优劣势与竞合关系评估</th>\n </tr>\n </thead>\n <tbody class=\"divide-y divide-slate-200 dark:divide-slate-800 text-xs sm:text-sm\" id=\"comp-table-body\">\n <tr data-category=\"core\" class=\"bg-lamorange-500/5 dark:bg-lamorange-500/10 font-medium\">\n <td class=\"py-4 px-5\">\n <div class=\"flex items-center space-x-2\">\n <span class=\"px-2 py-0.5 rounded bg-lamorange-500 text-white text-[10px] font-extrabold\">刻蚀霸主</span>\n <span class=\"font-bold text-slate-900 dark:text-white\">泛林集团 (Lam Research)</span>\n </div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Kiyo / Flex / SABRE / Altus</div>\n </td>\n <td class=\"py-4 px-4 font-semibold text-slate-900 dark:text-white\">等离子体刻蚀 + 薄膜淀积 + 洁净</td>\n <td class=\"py-4 px-4 font-bold text-lamorange-600 dark:text-lamorange-400\">3D NAND 刻蚀绝对第一 (~55%+)</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~32% (高黏性服务)</td>\n <td class=\"py-4 px-4 font-mono font-bold text-slate-900 dark:text-white\">~48% - 50%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>存储与刻蚀之王：</strong>在 3D NAND 与先进逻辑刻蚀领域具备断层优势，受益于存储器资本开支强劲复苏。\n </td>\n </tr>\n\n <tr data-category=\"wfe\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">应用材料 (Applied Materials / AMAT)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Centura / Producer / Endura</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">薄膜淀积、刻蚀、CMP、检查测量</td>\n <td class=\"py-4 px-4 font-semibold text-slate-700 dark:text-slate-300\">全球 WFE 综合营收第一</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~25% (AGS 服务)</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~47% - 49%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>全能型设备巨头：</strong>产品线最为丰富，但在 3D NAND 高深宽比刻蚀细分赛道上面临泛林的强力竞争。\n </td>\n </tr>\n\n <tr data-category=\"wfe\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">东京电子 (Tokyo Electron / TEL)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">Tactras / Certas / Clean Track</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">涂胶显影、刻蚀、清洗、CVD</td>\n <td class=\"py-4 px-4 font-semibold text-teal-600 dark:text-teal-400\">涂胶显影垄断 / 刻蚀第二梯队</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~25%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~45% - 48%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>日本半导体中坚：</strong>涂胶显影机（Coater/Developer）全球垄断，同时在介质刻蚀领域与泛林展开激烈竞争。\n </td>\n </tr>\n\n <tr data-category=\"etch\" class=\"hover:bg-slate-50 dark:hover:bg-navy-800/40 transition\">\n <td class=\"py-4 px-5\">\n <div class=\"font-bold text-slate-900 dark:text-white\">日立高新 (Hitachi High-Tech)</div>\n <div class=\"text-xs text-slate-500 dark:text-slate-400 mt-1\">BI系列的等离子体刻蚀机</div>\n </td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">介质刻蚀与电子显微镜</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">特定存储刻蚀份额</td>\n <td class=\"py-4 px-4 text-slate-700 dark:text-slate-300\">~20%</td>\n <td class=\"py-4 px-4 font-mono text-slate-700 dark:text-slate-300\">~38% - 42%</td>\n <td class=\"py-4 px-5 text-xs text-slate-600 dark:text-slate-300 leading-relaxed\">\n <strong>利基市场竞争者：</strong>在部分特定存储器刻蚀节点拥有稳定客户，但综合规模和产品丰富度不及泛林集团。\n </td>\n </tr>\n </tbody>\n </table>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">全球主要半导体设备厂商营业利润率（Operating Margin）对比</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">泛林集团 OPM 高达 ~32.2%，反映出高价值量刻蚀专利技术带来的强大盈利壁垒</p>\n </div>\n <span class=\"text-xs font-semibold text-lamorange-600 dark:text-lamorange-400 bg-lamorange-500/15 px-2.5 py-1 rounded\">刻蚀技术专利护城河支撑卓越盈利</span>\n </div>\n <div class=\"relative h-60 w-full\">\n <canvas id=\"compMarginChart\"></canvas>\n </div>\n </div>\n </section>\n\n <!-- 四、财务健康度与估值体系解析 -->\n <section id=\"sec-fin\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 04 · Financial Health & Valuation Framework</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">四、 财务健康度与估值体系：高自由现金流与极具吸引力的 PEG 估值</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">远期 P/E ~20.5x · PEG 0.45</span>\n </div>\n\n <div class=\"grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-lamorange-600 dark:text-lamorange-400 uppercase\">Gross Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">48% – 50%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 得益于先进刻蚀设备产品组合优化与高端存储器扩产需求，毛利率常年稳健维持在行业领先区间。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-emerald-600 dark:text-emerald-400 uppercase\">Operating Margin</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">32.2%</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 严谨的研发开支管控（占营收约 11%–12%）与高效的全球供应链运营，令营业利润率保持高位。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-teal-600 dark:text-teal-400 uppercase\">Free Cash Flow</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">~$4.5B+</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 稳定的盈利能力与轻资产运营模式带来充沛的自由现金流，为持续的股东回报奠定坚实基础。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"text-xs font-bold text-accent-600 dark:text-accent-400 uppercase\">Shareholder Return</div>\n <div class=\"text-2xl font-extrabold font-mono text-slate-900 dark:text-white mt-1\">80%+ Payout</div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1.5 leading-relaxed\">\n 通过大额股票回购计划与持续递增的现金股息，将绝大部分自由现金流回馈给长期股东。\n </p>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 mb-4\">\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base\">FY2021–FY2026E 营收、净利润演进与远期 P/E 估值倍数趋势</h3>\n <p class=\"text-xs text-slate-500 dark:text-slate-400\">存储周期回暖与 AI 算力扩产双重共振，远期 P/E 保持在 ~20.5x 合理健康区间</p>\n </div>\n <span class=\"text-xs font-mono font-bold text-emerald-600 dark:text-emerald-400 bg-emerald-500/10 px-2.5 py-1 rounded\">当前 PEG = 0.45</span>\n </div>\n <div class=\"relative h-72 w-full\">\n <canvas id=\"valEvolutionChart\"></canvas>\n </div>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-6\">\n <div class=\"bg-emerald-50/70 dark:bg-emerald-950/20 rounded-2xl p-6 border border-emerald-200 dark:border-emerald-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-emerald-700 dark:text-emerald-400 text-base\">多头核心论点 (Bull Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-emerald-500/15 text-emerald-700 dark:text-emerald-300\">存储升级刚需</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>3D NAND 层数翻倍带来刻蚀设备价值量暴增：</strong>随着存储密度提升至 300层以上，刻蚀工艺难度呈指数上升，泛林单片晶圆设备价值量大幅提升。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>CSBG 服务收入提供强劲安全垫：</strong>庞大的装机量带来高毛利的recurring revenue，有效对冲上游晶圆厂资本开支的周期性波动。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-emerald-600 font-bold\">✓</span><span><strong>合理的估值与高股东回报：</strong>20.5x 远期 P/E 搭配 PEG 0.45，结合大额回购，具备极高的长期投资性价比。</span></li>\n </ul>\n </div>\n\n <div class=\"bg-rose-50/70 dark:bg-rose-950/20 rounded-2xl p-6 border border-rose-200 dark:border-rose-800/60\">\n <div class=\"flex items-center justify-between mb-3\">\n <span class=\"font-bold text-rose-700 dark:text-rose-400 text-base\">空头担忧论点 (Bear Thesis)</span>\n <span class=\"text-xs font-semibold px-2.5 py-0.5 rounded-full bg-rose-500/15 text-rose-700 dark:text-rose-300\">周期与外部制约</span>\n </div>\n <ul class=\"space-y-2 text-xs sm:text-sm text-slate-700 dark:text-slate-300\">\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>半导体设备行业的周期性波动：</strong>存储器厂商（如三星、SK海力士、美光）的资本开支周期若出现波动，可能对泛林短期订单造成阶段性扰动。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>出口管制与地缘政治合规压力：</strong>针对特定海外市场的半导体设备出货合规政策可能对部分区域营收产生影响。</span></li>\n <li class=\"flex items-start space-x-2\"><span class=\"text-rose-600 font-bold\">!</span><span><strong>先进逻辑与存储竞争加剧：</strong>AMAT 和 TEL 在部分薄膜淀积与次世代刻蚀节点上的追赶压力。</span></li>\n </ul>\n </div>\n </div>\n </section>\n\n <!-- 五、投资决策与风险配置框架 -->\n <section id=\"sec-inv\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-lamorange-600 dark:text-lamorange-400\">Section 05 · Investment Decision & Risk Allocation</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">五、 投资决策与风险配置框架：三情景推演与资产配置建议</h2>\n </div>\n <span class=\"text-xs text-slate-500 dark:text-slate-400\">配置建议：全球半导体设备核心底仓 · 逢回调积极布局</span>\n </div>\n\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-5\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-lamorange-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-lamorange-500/15 text-lamorange-600 dark:text-lamorange-400 text-xs font-bold\">牛市情景 (Bull Case)</span>\n <span class=\"font-mono text-xs font-bold text-lamorange-600 dark:text-lamorange-400\">概率：30%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：25x – 28x P/E</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>AI 浪潮全面引爆 HBM 与超高层 3D NAND 强劲扩产，逻辑 GAA 架构转换超预期，FY27 营收增速维持 20% 以上，毛利率突破 50%。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-lamorange-600 dark:text-lamorange-400\">\n 潜在上行空间：+35% 至 +45%\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-accent-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-accent-500/15 text-accent-600 dark:text-accent-400 text-xs font-bold\">基准情景 (Base Case)</span>\n <span class=\"font-mono text-xs font-bold text-accent-600 dark:text-accent-400\">概率：50%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">目标估值：20x – 22x P/E</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>FY26E 营收如期达成 ~$21.5B 共识，存储与逻辑资本开支平稳复苏，CSBG 服务收入稳定增长，维持 ~48.5% 毛利率。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-accent-600 dark:text-accent-400\">\n 潜在上行空间：+15% 至 +25%（盈利稳健增长驱动）\n </div>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-2xl p-6 border-t-4 border-t-rose-500 border-x border-b border-slate-200 dark:border-slate-800 shadow-sm flex flex-col justify-between\">\n <div>\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2.5 py-0.5 rounded bg-rose-500/15 text-rose-600 dark:text-rose-400 text-xs font-bold\">熊市情景 (Bear Case)</span>\n <span class=\"font-mono text-xs font-bold text-rose-600 dark:text-rose-400\">概率：20%</span>\n </div>\n <div class=\"text-xl font-extrabold font-mono text-slate-900 dark:text-white mt-2\">防守估值：15x – 17x P/E</div>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2.5 leading-relaxed\">\n <strong>核心假设：</strong>全球存储芯片价格复苏不及预期导致内存厂商放缓扩产节奏，毛利率回落至 46% 附近，估值遭遇周期性压缩。\n </p>\n </div>\n <div class=\"mt-4 pt-3 border-t border-slate-100 dark:border-slate-800 text-xs font-semibold text-rose-600 dark:text-rose-400\">\n 潜在下行回撤：-15% 至 -20%（CSBG 服务现金流提供安全底线）\n </div>\n </div>\n </div>\n\n <div>\n <h3 class=\"font-bold text-slate-900 dark:text-white text-base mb-3\">四大核心风险评估与机构对冲缓释策略</h3>\n <div class=\"grid grid-cols-1 sm:grid-cols-2 gap-4\">\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-rose-500/10 text-rose-600 dark:text-rose-400 text-xs font-bold\">01 · 半导体周期与存储扩产波动风险</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">存储器大厂资本开支节奏调整</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 泛林集团对 NAND 与 DRAM 存储市场的收入暴露占比较高。若存储周期复苏斜率放缓，新设备出货可能面临阶段性调整。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-amber-500/10 text-amber-600 dark:text-amber-400 text-xs font-bold\">02 · 地缘政治与出口合规风险</span>\n <span class=\"text-xs font-mono text-amber-500 font-semibold\">关注度：高</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">跨境贸易管制与供应链合规政策</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 全球半导体设备出口受到严格监管，特定区域的合规政策可能对泛林部分成熟与先进制程设备的交付产生结构性影响。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-indigo-500/10 text-indigo-600 dark:text-indigo-400 text-xs font-bold\">03 · 同行竞争与份额挤压风险</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">AMAT 与 TEL 在细分刻蚀节点的竞争</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 竞争对手在介质刻蚀与原子层淀积（ALD）领域持续加大研发投入，需密切追踪泛林在 3D NAND 核心份额的维持情况。\n </p>\n </div>\n\n <div class=\"report-card bg-white dark:bg-navy-900 rounded-xl p-5 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <div class=\"flex items-center justify-between mb-2\">\n <span class=\"px-2 py-0.5 rounded bg-teal-500/10 text-teal-600 dark:text-teal-400 text-xs font-bold\">04 · 宏观经济与汇率波动风险</span>\n <span class=\"text-xs font-mono text-slate-500 font-semibold\">关注度：中</span>\n </div>\n <h4 class=\"font-bold text-slate-900 dark:text-white text-sm\">全球宏观经济走势与跨国汇率波动</h4>\n <p class=\"text-xs text-slate-600 dark:text-slate-300 mt-2 leading-relaxed\">\n 作为跨国高科技设备供应商，全球供应链成本波动及主要货币汇率变化可能对财务毛利率产生轻微扰动。\n </p>\n </div>\n </div>\n </div>\n\n <div class=\"bg-gradient-to-r from-navy-900 to-navy-800 rounded-2xl p-6 text-white border border-slate-700 shadow-md\">\n <h3 class=\"text-base font-bold text-lamorange-400 mb-4 flex items-center space-x-2\">\n <svg class=\"w-5 h-5\" fill=\"none\" stroke=\"currentColor\" viewBox=\"0 0 24 24\"><path stroke-linecap=\"round\" stroke-linejoin=\"round\" stroke-width=\"2\" d=\"M9 12l2 2 4-4m6 2a9 9 0 11-18 0 9 9 0 0118 0z\"/></svg>\n <span>机构级投资组合仓位配置与交易纪律建议</span>\n </h3>\n <div class=\"grid grid-cols-1 md:grid-cols-3 gap-4 text-xs sm:text-sm\">\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-white mb-1\">1. 核心设备底仓配置</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 作为全球半导体微观雕刻与 3D NAND 不可替代的王者，建议在科技与半导体设备组合中保持<strong>超配（Overweight）底仓</strong>。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-lamorange-400 mb-1\">2. 逢回调积极布局纪律</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 依托 ~20.5x 远期 P/E 与强劲的 CSBG 服务现金流底线，建议在半导体行业周期性震荡回调时分批建仓。\n </p>\n </div>\n <div class=\"bg-white/5 rounded-xl p-4 border border-white/10\">\n <div class=\"font-bold text-teal-400 mb-1\">3. 产业链协同组合配置</div>\n <p class=\"text-slate-300 leading-relaxed\">\n 可与光刻机龙头（ASML）、综合设备巨头（AMAT）及 AI 芯片设计龙头形成互补配置，分享 AI 与存储双轮驱动红利。\n </p>\n </div>\n </div>\n </div>\n </section>\n\n <!-- 六、季度基本面跟踪 KPI 交互式核查清单 -->\n <section id=\"sec-kpi\" class=\"scroll-mt-20 space-y-6\">\n <div class=\"border-b border-slate-200 dark:border-slate-800 pb-4 flex flex-col sm:flex-row sm:items-end justify-between gap-2\">\n <div>\n <span class=\"text-xs font-bold uppercase tracking-wider text-teal-600 dark:text-teal-400\">Section 06 · Quarterly Fundamental Tracking KPIs</span>\n <h2 class=\"text-2xl font-bold text-slate-900 dark:text-white mt-1\">六、 季度基本面跟踪 KPI 交互式核查清单（Checklist）</h2>\n </div>\n <div class=\"flex items-center space-x-2 no-print\">\n <span id=\"kpi-progress-badge\" class=\"px-3 py-1 rounded-full bg-lamorange-500/15 text-lamorange-600 dark:text-lamorange-400 text-xs font-bold\">已核查 3 / 6 项 (50%)</span>\n <button onclick=\"resetKpiChecklist()\" class=\"px-2.5 py-1 rounded-lg bg-slate-200/80 dark:bg-navy-800 hover:bg-slate-300 dark:hover:bg-navy-700 text-xs font-medium text-slate-700 dark:text-slate-300 transition\">重置清单</button>\n </div>\n </div>\n\n <div class=\"bg-white dark:bg-navy-900 rounded-2xl p-6 border border-slate-200 dark:border-slate-800 shadow-sm\">\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mb-4\">\n 点击勾选机构季报追踪已验证达标的指标（状态自动本地保存），用高频基本面事实动态校准估值安全边际：\n </p>\n\n <div class=\"grid grid-cols-1 md:grid-cols-2 gap-3.5\" id=\"kpi-checklist\">\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-1\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF6B00] focus:ring-lamorange-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">1. 3D NAND 300层+ 升级与设备订单占比</span>\n <span class=\"text-[11px] font-mono text-lamorange-600 dark:text-lamorange-400 font-semibold shrink-0\">存储核心锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪主流存储大厂在 300层以上 3D NAND 产线上的资本开支及泛林高深宽比刻蚀设备出货份额。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-2\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF6B00] focus:ring-lamorange-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">2. 逻辑 GAA 架构转换与先进代工设备渗透</span>\n <span class=\"text-[11px] font-mono text-teal-600 dark:text-teal-400 font-semibold shrink-0\">逻辑制程锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监测泛林在台积电、三星及英特尔 3nm/2nm GAA 逻辑芯片制造中的刻蚀与淀积设备获单情况。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-3\" checked onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF6B00] focus:ring-lamorange-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">3. CSBG 装机量服务板块季度营收稳定性</span>\n <span class=\"text-[11px] font-mono text-accent-600 dark:text-accent-400 font-semibold shrink-0\">服务现金流锚</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 检查 CSBG 业务是否维持单季稳定增长，验证庞大已装机基数对周期性波动的强大缓冲保护能力。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-4\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF6B00] focus:ring-lamorange-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">4. 综合毛利率是否稳守 48%–50% 黄金区间</span>\n <span class=\"text-[11px] font-mono text-emerald-600 dark:text-emerald-400 font-semibold shrink-0\">盈利红线</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 核查高端产品组合与供应链成本波动背景下，公司维持 48%–50% 稳态毛利率的定价能力。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-lamorange-500 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-5\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF6B00] focus:ring-lamorange-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">5. HBM 内存 TSV 刻蚀与封装设备出货</span>\n <span class=\"text-[11px] font-mono text-amber-600 dark:text-amber-400 font-semibold shrink-0\">AI 内存增量</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 跟踪面向 AI 算力堆叠内存（HBM）的硅通孔（TSV）刻蚀与电镀设备的交付增速。\n </p>\n </div>\n </label>\n\n <label class=\"flex items-start space-x-3 p-4 rounded-xl border border-slate-200 dark:border-slate-700 hover:bg-slate-50 dark:hover:bg-navy-800/50 cursor-pointer transition\">\n <input type=\"checkbox\" id=\"kpi-6\" onchange=\"updateKpiChecklist()\" class=\"mt-1 w-4 h-4 rounded accent-[#FF6B00] focus:ring-lamorange-500\">\n <div class=\"flex-1\">\n <div class=\"flex items-center justify-between gap-2\">\n <span class=\"font-bold text-sm text-slate-900 dark:text-white\">6. 自由现金流与大额股票回购执行力度</span>\n <span class=\"text-[11px] font-mono text-indigo-600 dark:text-indigo-400 font-semibold shrink-0\">股东回报指标</span>\n </div>\n <p class=\"text-xs text-slate-500 dark:text-slate-400 mt-1 leading-relaxed\">\n 监测每季度自由现金流生成情况及管理层对股票回购与分红的执行进度。\n </p>\n </div>\n </label>\n </div>\n </div>\n </section>\n\n <!-- 页脚免责声明 -->\n <footer class=\"pt-8 border-t border-slate-200 dark:border-slate-800 text-xs text-slate-500 dark:text-slate-400 space-y-2 pb-10\">\n <div class=\"flex flex-col sm:flex-row sm:items-center justify-between gap-2 font-semibold text-slate-700 dark:text-slate-300\">\n <span>泛林集团 Lam Research (NASDAQ: LRCX) 深度商业与投资价值分析报告 · 机构研究框架版</span>\n <span>数据基准：FY2025 财报及 2026 年 11 月市场一致预期</span>\n </div>\n <p class=\"leading-relaxed\">\n <strong>免责声明：</strong>本深度研究报告基于公司公开财务报告、半导体设备产业链调研及市场一致预期数据整理生成，旨在提供结构化的产业分析与机构估值研究框架。报告中涉及的未来营收预测、技术市占率、三情景估值模型及概率分布均基于特定产业假设，不构成任何具体的证券买卖建议、要约或投资承诺。投资者在做出任何资产配置决策前，应结合自身风险承受能力与独立尽职调查审慎判断。\n </p>\n </footer>\n\n </div>\n </main>\n\n <script>\n function toggleTheme() {\n const html = document.documentElement;\n html.classList.toggle('dark');\n updateChartsTheme();\n }\n\n function toggleMobileMenu() {\n const drawer = document.getElementById('mobile-drawer');\n drawer.classList.toggle('hidden');\n }\n\n const sections = document.querySelectorAll('section[id]');\n const navLinks = document.querySelectorAll('#desktop-nav .nav-link');\n\n window.addEventListener('scroll', () => {\n const scrollTop = window.scrollY;\n const docHeight = document.documentElement.scrollHeight - window.innerHeight;\n const scrollPercent = docHeight > 0 ? (scrollTop / docHeight) * 100 : 0;\n document.getElementById('reading-progress').style.width = `${Math.min(100, Math.max(0, scrollPercent))}%`;\n\n let currentId = 'sec-exec';\n sections.forEach(sec => {\n const top = sec.offsetTop - 160;\n if (scrollTop >= top) {\n currentId = sec.getAttribute('id');\n }\n });\n\n navLinks.forEach(link => {\n link.classList.remove('active');\n const numSpan = link.querySelector('span span');\n if (numSpan) {\n numSpan.classList.remove('text-lamorange-400');\n numSpan.classList.add('text-slate-500');\n }\n if (link.dataset.target === currentId) {\n link.classList.add('active');\n if (numSpan) {\n numSpan.classList.remove('text-slate-500');\n numSpan.classList.add('text-lamorange-400');\n }\n }\n });\n });\n\n function filterCompetitors(category) {\n document.querySelectorAll('.comp-filter-btn').forEach(btn => {\n if (btn.dataset.filter === category) {\n btn.classList.add('bg-lamorange-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.remove('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n } else {\n btn.classList.remove('bg-lamorange-500', 'text-white', 'font-semibold', 'shadow-sm');\n btn.classList.add('bg-white', 'dark:bg-navy-800', 'text-slate-600', 'dark:text-slate-300', 'border', 'font-medium');\n }\n });\n\n const rows = document.querySelectorAll('#comp-table-body tr');\n rows.forEach(row => {\n const rowCat = row.dataset.category;\n if (category === 'all' || rowCat === 'core' || rowCat === category) {\n row.style.display = '';\n } else {\n row.style.display = 'none';\n }\n });\n }\n\n const KPI_STORAGE_KEY = 'lrcx_research_kpi_state_v1';\n\n function loadKpiChecklist() {\n try {\n const saved = localStorage.getItem(KPI_STORAGE_KEY);\n if (saved) {\n const stateMap = JSON.parse(saved);\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n if (typeof stateMap[cb.id] === 'boolean') {\n cb.checked = stateMap[cb.id];\n }\n });\n }\n } catch (e) {}\n updateKpiChecklist();\n }\n\n function updateKpiChecklist() {\n const checkboxes = document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]');\n const total = checkboxes.length;\n let checkedCount = 0;\n const stateMap = {};\n\n checkboxes.forEach(cb => {\n stateMap[cb.id] = cb.checked;\n if (cb.checked) checkedCount++;\n });\n\n const pct = Math.round((checkedCount / total) * 100);\n document.getElementById('kpi-progress-badge').textContent = `已核查 ${checkedCount} / ${total} 项 (${pct}%)`;\n\n try {\n localStorage.setItem(KPI_STORAGE_KEY, JSON.stringify(stateMap));\n } catch (e) {}\n }\n\n function resetKpiChecklist() {\n document.querySelectorAll('#kpi-checklist input[type=\"checkbox\"]').forEach(cb => {\n cb.checked = false;\n });\n updateKpiChecklist();\n }\n\n let bizChartInstance = null;\n let radarChartInstance = null;\n let compMarginChartInstance = null;\n let valEvolutionChartInstance = null;\n let currentBizMode = 'evolution';\n\n function getChartColors() {\n const isDark = document.documentElement.classList.contains('dark');\n return {\n text: isDark ? '#CBD5E1' : '#475569',\n grid: isDark ? 'rgba(51, 65, 85, 0.5)' : 'rgba(226, 232, 240, 0.85)',\n radarAngle: isDark ? 'rgba(71, 85, 105, 0.6)' : 'rgba(203, 213, 225, 0.85)'\n };\n }\n\n function initBizChart() {\n const ctx = document.getElementById('bizArchitectureChart').getContext('2d');\n const colors = getChartColors();\n\n const evoConfig = {\n type: 'bar',\n data: {\n labels: ['FY2021', 'FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E'],\n datasets: [\n {\n label: '存储器 (NAND / DRAM)',\n data: [8.5, 10.2, 9.1, 7.8, 10.1, 12.2],\n backgroundColor: '#FF6B00',\n borderRadius: 4,\n },\n {\n label: '先进制程逻辑与代工 (Foundry)',\n data: [5.2, 6.8, 5.5, 4.9, 5.3, 6.8],\n backgroundColor: '#3B82F6',\n borderRadius: 4,\n },\n {\n label: 'CSBG 客户服务与其他',\n data: [3.6, 4.2, 4.6, 4.6, 2.4, 2.5],\n backgroundColor: '#06B6D4',\n borderRadius: 4,\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => `${ctx.dataset.label}: $${ctx.parsed.y}B`\n }\n }\n },\n scales: {\n x: {\n stacked: true,\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n stacked: true,\n max: 25,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n }\n }\n }\n };\n\n const splitConfig = {\n type: 'bar',\n data: {\n labels: [\n '下游平台：3D NAND 存储器',\n '下游平台：Foundry 逻辑先进制程',\n '下游平台：CSBG 装机量服务',\n '下游平台：DRAM 与 HBM 内存'\n ],\n datasets: [\n {\n label: 'FY2025 业务板块占比 (%)',\n data: [40.0, 30.0, 18.0, 12.0],\n backgroundColor: [\n '#FF6B00',\n '#3B82F6',\n '#06B6D4',\n '#10B981'\n ],\n borderRadius: 6,\n barThickness: 26\n }\n ]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `业务板块占比: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 50,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n };\n\n if (bizChartInstance) bizChartInstance.destroy();\n bizChartInstance = new Chart(ctx, currentBizMode === 'evolution' ? evoConfig : splitConfig);\n }\n\n function switchBizChart(mode) {\n currentBizMode = mode;\n const btnEvo = document.getElementById('btn-chart-evo');\n const btnSplit = document.getElementById('btn-chart-split');\n const titleEl = document.getElementById('biz-chart-title');\n const subEl = document.getElementById('biz-chart-sub');\n\n if (mode === 'evolution') {\n btnEvo.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-lamorange-600 dark:text-lamorange-400 shadow-sm transition';\n btnSplit.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n titleEl.textContent = 'FY2021–FY2026E 营收演进与下游存储/逻辑结构占比';\n subEl.textContent = '存储器（NAND/DRAM）与先进逻辑芯片复苏带动年营收向 $21B+ 迈进';\n } else {\n btnSplit.className = 'px-2.5 py-1 rounded-md font-semibold bg-white dark:bg-navy-700 text-lamorange-600 dark:text-lamorange-400 shadow-sm transition';\n btnEvo.className = 'px-2.5 py-1 rounded-md font-medium text-slate-600 dark:text-slate-400 hover:text-slate-900 dark:hover:text-white transition';\n titleEl.textContent = 'FY2025 下游应用市场业务板块占比拆解';\n subEl.textContent = '3D NAND (40%) 与 Foundry 逻辑 (30%) 构成核心收入基石';\n }\n initBizChart();\n }\n\n function initRadarChart() {\n const ctx = document.getElementById('moatRadarChart').getContext('2d');\n const colors = getChartColors();\n\n if (radarChartInstance) radarChartInstance.destroy();\n radarChartInstance = new Chart(ctx, {\n type: 'radar',\n data: {\n labels: [\n '超高深宽比刻蚀技术壁垒',\n 'Installed Base 装机量与服务网',\n '与全球顶级晶圆厂联合研发深度',\n '刻蚀与薄膜淀积（Etch+Dep）协同',\n '精密射频与深冷控制专利'\n ],\n datasets: [\n {\n label: '泛林集团 (Lam Research)',\n data: [9.9, 9.6, 9.7, 9.8, 9.9],\n borderColor: '#FF6B00',\n backgroundColor: 'rgba(255, 107, 0, 0.22)',\n pointBackgroundColor: '#FF6B00',\n borderWidth: 2.5\n },\n {\n label: '应用材料 (AMAT)',\n data: [8.2, 9.0, 9.5, 9.7, 8.0],\n borderColor: '#3B82F6',\n backgroundColor: 'rgba(59, 130, 246, 0.14)',\n pointBackgroundColor: '#3B82F6',\n borderWidth: 1.8\n },\n {\n label: '东京电子 (TEL)',\n data: [8.5, 8.2, 8.8, 8.5, 8.3],\n borderColor: '#94A3B8',\n backgroundColor: 'rgba(148, 163, 184, 0.12)',\n pointBackgroundColor: '#94A3B8',\n borderWidth: 1.5,\n borderDash: [4, 4]\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11 }, usePointStyle: true }\n }\n },\n scales: {\n r: {\n min: 0,\n max: 10,\n ticks: { display: false, stepSize: 2 },\n grid: { color: colors.grid },\n angleLines: { color: colors.radarAngle },\n pointLabels: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initCompMarginChart() {\n const ctx = document.getElementById('compMarginChart').getContext('2d');\n const colors = getChartColors();\n\n if (compMarginChartInstance) compMarginChartInstance.destroy();\n compMarginChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: [\n '泛林集团 (Lam Research · 刻蚀霸主)',\n '应用材料 (AMAT · 综合设备巨头)',\n '东京电子 (TEL · 涂胶显影/刻蚀)',\n '泛林集团平均长期目标'\n ],\n datasets: [{\n label: '营业利润率 Operating Margin (%)',\n data: [32.2, 29.5, 27.8, 30.0],\n backgroundColor: [\n '#FF6B00',\n '#3B82F6',\n '#06B6D4',\n '#94A3B8'\n ],\n borderRadius: 6,\n barThickness: 24\n }]\n },\n options: {\n indexAxis: 'y',\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: { display: false },\n tooltip: {\n callbacks: {\n label: (ctx) => `营业利润率: ${ctx.parsed.x}%`\n }\n }\n },\n scales: {\n x: {\n max: 45,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => v + '%' }\n },\n y: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n }\n }\n }\n });\n }\n\n function initValEvolutionChart() {\n const ctx = document.getElementById('valEvolutionChart').getContext('2d');\n const colors = getChartColors();\n\n if (valEvolutionChartInstance) valEvolutionChartInstance.destroy();\n valEvolutionChartInstance = new Chart(ctx, {\n type: 'bar',\n data: {\n labels: ['FY2021', 'FY2022', 'FY2023', 'FY2024', 'FY2025', 'FY2026E'],\n datasets: [\n {\n type: 'bar',\n label: '全年总营收 ($B)',\n data: [14.6, 17.2, 17.4, 14.9, 17.8, 21.5],\n backgroundColor: 'rgba(255, 107, 0, 0.85)',\n borderRadius: 5,\n barThickness: 24,\n yAxisID: 'y'\n },\n {\n type: 'bar',\n label: '全年净利润 ($B)',\n data: [4.6, 5.8, 5.0, 3.9, 4.9, 6.2],\n backgroundColor: 'rgba(59, 130, 246, 0.85)',\n borderRadius: 5,\n barThickness: 24,\n yAxisID: 'y'\n },\n {\n type: 'line',\n label: '远期市盈率 Forward P/E (x)',\n data: [22.0, 14.5, 19.5, 26.0, 23.0, 20.5],\n borderColor: '#F59E0B',\n backgroundColor: '#F59E0B',\n borderWidth: 3,\n pointRadius: 5,\n pointHoverRadius: 7,\n tension: 0.25,\n yAxisID: 'y1'\n }\n ]\n },\n options: {\n responsive: true,\n maintainAspectRatio: false,\n plugins: {\n legend: {\n position: 'bottom',\n labels: { color: colors.text, font: { size: 11, family: 'Inter' }, usePointStyle: true }\n },\n tooltip: {\n callbacks: {\n label: (ctx) => ctx.dataset.yAxisID === 'y'\n ? `${ctx.dataset.label}: $${ctx.parsed.y}B`\n : `${ctx.dataset.label}: ${ctx.parsed.y}x`\n }\n }\n },\n scales: {\n x: {\n grid: { display: false },\n ticks: { color: colors.text, font: { size: 11, weight: '600' } }\n },\n y: {\n type: 'linear',\n position: 'left',\n max: 30,\n grid: { color: colors.grid },\n ticks: { color: colors.text, font: { size: 11 }, callback: v => '$' + v + 'B' }\n },\n y1: {\n type: 'linear',\n position: 'right',\n min: 0,\n max: 40,\n grid: { drawOnChartArea: false },\n ticks: { color: '#F59E0B', font: { size: 11, weight: '600' }, callback: v => v + 'x' }\n }\n }\n }\n });\n }\n\n function updateChartsTheme() {\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n }\n\n window.addEventListener('DOMContentLoaded', () => {\n loadKpiChecklist();\n initBizChart();\n initRadarChart();\n initCompMarginChart();\n initValEvolutionChart();\n });\n </script>\n</body>\n</html>\n"};
